import { Service, signal } from '@angular/core';

export type ToastTipo = 'success' | 'error' | 'info' | 'warning';

export interface Toast {
  id: number;
  tipo: ToastTipo;
  texto: string;
}

@Service()
export class ToastService {
  readonly toasts = signal<Toast[]>([]);

  private nextId = 1;
  private timeouts = new Map<number, ReturnType<typeof setTimeout>>();

  success(texto: string): void {
    this.show('success', texto);
  }

  error(texto: string): void {
    this.show('error', texto);
  }

  info(texto: string): void {
    this.show('info', texto);
  }

  warning(texto: string): void {
    this.show('warning', texto);
  }

  dismiss(id: number): void {
    const handle = this.timeouts.get(id);
    if (handle !== undefined) {
      clearTimeout(handle);
      this.timeouts.delete(id);
    }
    this.toasts.update((list) => list.filter((t) => t.id !== id));
  }

  private show(tipo: ToastTipo, texto: string): void {
    const id = this.nextId++;
    this.toasts.update((list) => [...list, { id, tipo, texto }]);
    const handle = setTimeout(() => this.dismiss(id), 4000);
    this.timeouts.set(id, handle);
  }
}
